class AttachmentInfo:
    """
    A file embedded in the document.
"""
    def __init__(self, *, name:str, description:typing.Optional[str], size:typing.Optional[int], on_page:bool):
        self.name = name
        self.description = description
        self.size = size
        self.on_page = on_page




    def __str__(self):
        return "AttachmentInfo(name={}, description={}, size={}, on_page={})".format(self.name, self.description, self.size, self.on_page)
    def __eq__(self, other):
        if self.name != other.name:
            return False
        if self.description != other.description:
            return False
        if self.size != other.size:
            return False
        if self.on_page != other.on_page:
            return False
        return True

