# MobileError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class MobileError(Exception):
    """
    What went wrong, as a message the user can act on.
"""
    pass

_UniffiTempMobileError = MobileError

class MobileError:  # type: ignore
    """
    What went wrong, as a message the user can act on.
"""

    class Command(_UniffiTempMobileError):
        """
        A tool failed or was refused: unknown name, bad arguments, not allowed by the document…
"""
        def __repr__(self):
            return "MobileError.Command({})".format(repr(str(self)))
    _UniffiTempMobileError.Command = Command # type: ignore
    class Open(_UniffiTempMobileError):
        """
        The file could not be opened as a PDF.
"""
        def __repr__(self):
            return "MobileError.Open({})".format(repr(str(self)))
    _UniffiTempMobileError.Open = Open # type: ignore
    class NeedsPassword(_UniffiTempMobileError):
        """
        The document needs a password to open.
"""
        def __repr__(self):
            return "MobileError.NeedsPassword({})".format(repr(str(self)))
    _UniffiTempMobileError.NeedsPassword = NeedsPassword # type: ignore
    class WrongPassword(_UniffiTempMobileError):
        """
        The password given doesn't open the document.
"""
        def __repr__(self):
            return "MobileError.WrongPassword({})".format(repr(str(self)))
    _UniffiTempMobileError.WrongPassword = WrongPassword # type: ignore
    class Render(_UniffiTempMobileError):
        """
        A page could not be drawn.
"""
        def __repr__(self):
            return "MobileError.Render({})".format(repr(str(self)))
    _UniffiTempMobileError.Render = Render # type: ignore
    class NoDocument(_UniffiTempMobileError):
        def __repr__(self):
            return "MobileError.NoDocument({})".format(repr(str(self)))
    _UniffiTempMobileError.NoDocument = NoDocument # type: ignore

MobileError = _UniffiTempMobileError # type: ignore
del _UniffiTempMobileError


class _UniffiFfiConverterTypeMobileError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return MobileError.Command(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return MobileError.Open(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return MobileError.NeedsPassword(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 4:
            return MobileError.WrongPassword(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return MobileError.Render(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 6:
            return MobileError.NoDocument(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, MobileError.Command):
            return
        if isinstance(value, MobileError.Open):
            return
        if isinstance(value, MobileError.NeedsPassword):
            return
        if isinstance(value, MobileError.WrongPassword):
            return
        if isinstance(value, MobileError.Render):
            return
        if isinstance(value, MobileError.NoDocument):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, MobileError.Command):
            buf.write_i32(1)
        if isinstance(value, MobileError.Open):
            buf.write_i32(2)
        if isinstance(value, MobileError.NeedsPassword):
            buf.write_i32(3)
        if isinstance(value, MobileError.WrongPassword):
            buf.write_i32(4)
        if isinstance(value, MobileError.Render):
            buf.write_i32(5)
        if isinstance(value, MobileError.NoDocument):
            buf.write_i32(6)

