class _UniffiFfiConverterTypeMobileSession:
    @staticmethod
    def lift(value: int) -> MobileSession:
        return MobileSession._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: MobileSession):
        if not isinstance(value, MobileSession):
            raise TypeError("Expected MobileSession instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: MobileSession) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> MobileSession:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: MobileSession, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))
